					title="Edit"
					@click="enterEditMode"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-5 w-5"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="M12 20h9" />
						<path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z" />
					</svg>
				</button>
			</div>
		</div>

		<!-- ============ KONTEN ============ -->
		<div class="flex flex-1 flex-col">
			<p v-if="pageLoading" class="px-6 py-4 text-sm text-ui-ink-gray-500">Loading...</p>

			<pre
				v-else-if="doc.error"
				class="px-6 py-4 text-sm text-ui-ink-red-600 whitespace-pre-wrap"
				>{{ doc.error.message || doc.error }}</pre
			>

			<div v-else-if="doc.data || isAmend" class="text-base">
				<div class="space-y-4 px-4 py-5 md:px-6">
					<template v-if="renderedSections.length">
						<section
							v-for="(sec, si) in renderedSections"
							:key="si"
							class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
						>
							<h3 v-if="sec.label" class="mb-3 text-lg font-semibold text-primary">
								{{ sec.label }}
							</h3>
							<div class="flex flex-col gap-x-6 gap-y-4 md:flex-row">
								<div
									v-for="(col, ci) in sec.columns"
									:key="ci"
									class="flex-1 space-y-4"
								>
									<div v-for="field in col" :key="field.fieldname">
										<label
											class="mb-1 block text-base font-medium text-ui-ink-gray-500"
										>
											{{ field.label }}
											<span
												v-if="isFieldReqd(field) && editMode"
												class="text-ui-ink-red-500"
												>*</span
											>
										</label>

										<!-- ===== MODE BACA ===== -->
										<template v-if="!editMode">
											<img
												v-if="
													isImageField(field.fieldtype) &&
													doc.data[field.fieldname]
												"
												:src="doc.data[field.fieldname]"
												:alt="field.label"
												class="mt-1 max-h-56 rounded-lg border border-ui-line-gray-200 object-contain"
											/>
											<a
												v-else-if="
													field.fieldtype === 'Attach' &&
													doc.data[field.fieldname]
												"
												:href="doc.data[field.fieldname]"
												target="_blank"
												rel="noopener"
												class="break-all text-base text-primary underline"
												@click.prevent="
													openAttachment(
														doc.data[field.fieldname],
														field.label
													)
												"
											>
												{{ fileName(doc.data[field.fieldname]) }}
											</a>
											<p
												v-else-if="field.fieldtype === 'Link'"
												class="min-h-[1.25rem] break-words text-base text-ui-ink-gray-800"
											>
												{{ linkDisplay(field) || '—' }}
											</p>
											<p
												v-else-if="field.fieldtype === 'Check'"
												class="min-h-[1.25rem] text-base text-ui-ink-gray-800"
											>
												{{ doc.data[field.fieldname] ? 'Ya' : 'Tidak' }}
											</p>
											<p
												v-else-if="field.fieldtype === 'Currency'"
												class="min-h-[1.25rem] text-base font-medium text-ui-ink-gray-900"
											>
												{{
													currencyDisplay(doc.data[field.fieldname]) ||
													'—'
												}}
											</p>
											<p
												v-else-if="
													['Date', 'Datetime'].includes(field.fieldtype)
												"
												class="min-h-[1.25rem] text-base text-ui-ink-gray-800"
											>
												{{
													formatDateDisplay(doc.data[field.fieldname]) ||
													'—'
												}}
											</p>
											<p
												v-else-if="isTextarea(field.fieldtype)"
												class="min-h-[1.25rem] whitespace-pre-line break-words text-base text-ui-ink-gray-800"
											>
												{{ doc.data[field.fieldname] || '—' }}
											</p>
											<p
												v-else
												class="min-h-[1.25rem] break-words text-base text-ui-ink-gray-800"
											>
												{{
													doc.data[field.fieldname] == null ||
													doc.data[field.fieldname] === ''
														? '—'
														: doc.data[field.fieldname]
												}}
											</p>
										</template>

										<!-- ===== MODE EDIT ===== -->
										<template v-else>
											<!-- Select -->
											<SelectMenu
												v-if="field.fieldtype === 'Select'"
												v-model="form[field.fieldname]"
												:options="selectOptions(field)"
												:disabled="isFieldReadOnly(field)"
												:clearable="!isFieldReqd(field)"
												placeholder="Pilih…"
												:btn-class="fieldClass(field)"
											/>

											<!-- Date -->
											<input
												v-else-if="field.fieldtype === 'Date'"
												v-model="form[field.fieldname]"
												type="date"
												:disabled="isFieldReadOnly(field)"
												:class="fieldClass(field)"
											/>

											<!-- Check -->
											<label
												v-else-if="field.fieldtype === 'Check'"
												class="flex min-h-[44px] items-center gap-2 md:min-h-0"
											>
												<input
													type="checkbox"
													:checked="!!form[field.fieldname]"
													:disabled="isFieldReadOnly(field)"
													class="h-5 w-5 rounded border-ui-line-gray-300 text-primary focus:ring-primary disabled:cursor-not-allowed disabled:opacity-50"
													@change="
														form[field.fieldname] = $event.target
															.checked
															? 1
															: 0
													"
												/>
												<span class="text-sm text-ui-ink-gray-600">Ya</span>
											</label>

											<!-- Textarea -->
											<textarea
												v-else-if="isTextarea(field.fieldtype)"
												v-model="form[field.fieldname]"
												v-autogrow
												rows="2"
												:maxlength="field.length || undefined"
												:readonly="isFieldReadOnly(field)"
												:class="[fieldClass(field), 'resize-none']"
											/>

											<!-- Currency -->
											<input
												v-else-if="field.fieldtype === 'Currency'"
												type="text"
												inputmode="decimal"
												:value="currencyDisplay(form[field.fieldname])"
												:readonly="isFieldReadOnly(field)"
												:class="fieldClass(field)"
												@focus="
													$event.target.value =
														form[field.fieldname] ?? ''
												"
												@blur="onCurrencyBlur(field, $event)"
											/>

											<!-- Angka lain -->
											<input
												v-else-if="isNumberField(field.fieldtype)"
												v-model="form[field.fieldname]"
												type="number"
												inputmode="decimal"
												:readonly="isFieldReadOnly(field)"
												:class="fieldClass(field)"
											/>

											<!-- Attach / Attach Image → upload bila boleh edit -->
											<div
												v-else-if="
													['Attach', 'Attach Image'].includes(
														field.fieldtype
													)
												"
												class="space-y-2"
											>
												<div
													v-if="form[field.fieldname]"
													class="flex items-center justify-between gap-2 rounded-md border border-ui-line-gray-200 bg-ui-surface-gray-50 px-3 py-2"
												>
													<a
														:href="form[field.fieldname]"
														target="_blank"
														rel="noopener"
														class="min-w-0 truncate text-sm font-medium text-primary hover:underline"
													>
														{{ fileName(form[field.fieldname]) }}
													</a>
													<button
														v-if="!isFieldReadOnly(field)"
														type="button"
														class="flex h-7 w-7 shrink-0 items-center justify-center rounded-md text-ui-ink-red-500 transition hover:bg-ui-surface-red-50"
														aria-label="Hapus file"
														@click="form[field.fieldname] = ''"
													>
														<svg
															xmlns="http://www.w3.org/2000/svg"
															viewBox="0 0 24 24"
															class="h-4 w-4"
															fill="none"
															stroke="currentColor"
															stroke-width="2"
															stroke-linecap="round"
															stroke-linejoin="round"
														>
															<path d="M3 6h18" />
															<path
																d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"
															/>
															<path
																d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"
															/>
														</svg>
													</button>
												</div>
												<button
													v-if="!isFieldReadOnly(field)"
													type="button"
													:disabled="uploadingField === field.fieldname"
													class="flex w-full items-center gap-2 rounded-md border border-dashed border-ui-line-gray-300 px-3 py-2.5 text-left text-sm text-ui-ink-gray-500 transition hover:border-primary disabled:opacity-50"
													@click="triggerUpload(field)"
												>
													<svg
														xmlns="http://www.w3.org/2000/svg"
														viewBox="0 0 24 24"
														class="h-5 w-5 shrink-0"
														fill="none"
														stroke="currentColor"
														stroke-width="1.8"
														stroke-linecap="round"
														stroke-linejoin="round"
													>
														<path
															d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"
														/>
														<path d="M17 8l-5-5-5 5" />
														<path d="M12 3v12" />
													</svg>
													{{
														uploadingField === field.fieldname
															? 'Mengunggah…'
															: form[field.fieldname]
															? 'Ganti file'
															: 'Pilih file (PDF/JPG/PNG, maks 3 MB)'
													}}
												</button>
											</div>

											<!-- Link → searchable -->
											<div
												v-else-if="field.fieldtype === 'Link'"
												class="relative"
											>
												<button
													type="button"
													:disabled="isFieldReadOnly(field)"
													:class="[
														fieldClass(field),
														'flex items-center justify-between gap-2 text-left',
													]"
													@click="toggleLinkDropdown(field)"
												>
													<span
														class="min-w-0 truncate font-bold text-ui-ink-gray-900"
													>
														{{ linkDisplay(field) || 'Pilih…' }}
													</span>
													<svg
														xmlns="http://www.w3.org/2000/svg"
														viewBox="0 0 24 24"
														class="h-4 w-4 shrink-0 text-ui-ink-gray-400"
														fill="none"
														stroke="currentColor"
														stroke-width="2"
														stroke-linecap="round"
														stroke-linejoin="round"
													>
														<path d="m6 9 6 6 6-6" />
													</svg>
												</button>
												<div
													v-if="openDropdown === field.fieldname"
													class="absolute left-0 right-0 z-20 mt-1.5 overflow-hidden rounded-xl border border-ui-line-gray-200 bg-ui-surface shadow-xl ring-1 ring-black/5"
												>
													<div class="border-b border-ui-line-gray-100 p-2">
														<input
															v-model="linkSearch"
															type="text"
															placeholder="Cari…"
															:class="inputClass"
															@click.stop
															@input="onLinkSearch(field)"
														/>
													</div>
													<div class="max-h-56 overflow-y-auto p-1">
														<button
															v-for="opt in linkResults"
															:key="opt.value"
															type="button"
															class="flex w-full flex-col items-start rounded-lg px-3 py-2 text-left transition"
															:class="
																optionMatch(opt, field)
																	? 'bg-ui-surface-gray-100'
																	: 'hover:bg-ui-surface-gray-50'
															"
															@click="
																selectLink(
																	field,
																	opt.value,
																	opt.label
																)
															"
														>
															<span
																class="font-bold text-ui-ink-gray-900"
																>{{ opt.label }}</span
															>
															<span
																v-if="opt.value !== opt.label"
																class="text-xs text-ui-ink-gray-400"
																>{{ opt.value }}</span
															>
														</button>
														<p
															v-if="!linkResults.length"
															class="px-3 py-2 text-xs text-ui-ink-gray-400"
														>
															{{
																linkSearchLoading
																	? 'Mencari…'
																	: 'Tidak ada hasil'
															}}
														</p>
													</div>
												</div>
											</div>

											<!-- Default: Data / lainnya -->
											<input
												v-else
												v-model="form[field.fieldname]"
												type="text"
												:maxlength="field.length || undefined"
												:readonly="isFieldReadOnly(field)"
												:class="fieldClass(field)"
											/>
										</template>
									</div>
								</div>
							</div>
						</section>

						<!-- Penutup dropdown Link saat klik di luar -->
						<div
							v-if="openDropdown"
							class="fixed inset-0 z-10"
							@click="openDropdown = ''"
						/>
					</template>

					<p v-else class="py-10 text-center text-sm text-ui-ink-gray-400">
						{{
							metaFields.length
								? 'Tidak ada data yang dapat ditampilkan.'
								: 'Memuat…'
						}}
					</p>
				</div>

				<!-- Ruang bawah agar konten tidak tertutup bottom bar. -->
				<div v-if="showBottomBar" class="bottom-bar-spacer" />
			</div>
		</div>

		<!-- Hidden file input (Attach upload) -->
		<input
			ref="fileInput"
			type="file"
			class="hidden"
			accept=".pdf,image/*"
			@change="onFileChange"
		/>

		<!-- ====== Bottom bar: Save (mode edit) atau Actions (mode baca) ====== -->
		<Transition
			enter-active-class="transition duration-200 ease-out"
			enter-from-class="translate-y-2 opacity-0"
			leave-active-class="transition duration-150 ease-in"
			leave-to-class="translate-y-2 opacity-0"
		>
			<div
				v-if="showBottomBar"
				class="fixed inset-x-0 bottom-0 z-20 border-t border-ui-line-gray-200 bg-ui-surface px-4 py-3 md:px-6"
				style="padding-bottom: calc(0.75rem + env(safe-area-inset-bottom))"
			>
				<div class="mx-auto max-w-screen-sm">
					<!-- Mode edit → Batal + Save -->
					<div v-if="editMode" class="flex items-center gap-2">
						<button
							type="button"
							class="flex-1 rounded-full border border-ui-line-gray-300 bg-ui-surface py-3 text-sm font-semibold text-ui-ink-gray-700 transition hover:bg-ui-surface-gray-50"
							@click="cancelEdit"
						>
							Batal
						</button>
						<button
							type="button"
							:disabled="saving"
							class="flex flex-[2] items-center justify-center gap-2 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.99] disabled:cursor-not-allowed disabled:opacity-50"
							@click="saveDocument"
						>
							<svg
								v-if="saving"
								xmlns="http://www.w3.org/2000/svg"
								viewBox="0 0 24 24"
								class="h-4 w-4 animate-spin"
								fill="none"
								stroke="currentColor"
								stroke-width="2"
								stroke-linecap="round"
								stroke-linejoin="round"
							>
								<path d="M21 12a9 9 0 1 1-6.219-8.56" />
							</svg>
							{{ saving ? 'Menyimpan…' : 'Save' }}
						</button>
					</div>

					<!-- Mode baca → Actions (transisi workflow &/atau Amend) -->
					<button
						v-else-if="transitions.items.length || amendState.can"
						type="button"
						class="flex w-full items-center justify-center gap-2 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.99]"
						@click="actionsOpen = true"
					>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-4 w-4"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<circle cx="12" cy="12" r="1" />
							<circle cx="19" cy="12" r="1" />
							<circle cx="5" cy="12" r="1" />
						</svg>
						Actions
					</button>
				</div>
			</div>
		</Transition>

		<!-- ====== Bottom-sheet daftar Actions ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="actionsOpen"
					class="fixed inset-0 z-[70] flex items-end justify-center bg-black/40"
					@click.self="actionsOpen = false"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="actionsOpen"
							class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 text-xs shadow-2xl"
						>
							<div class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300" />
							<h2 class="mb-4 text-center text-base font-semibold text-ui-ink-gray-900">
								Actions
							</h2>

							<p
								v-if="transitions.loading"
								class="py-3 text-center text-sm text-ui-ink-gray-400"
							>
								Memuat aksi…
							</p>
							<p
								v-else-if="!transitions.items.length && !amendState.can"
								class="py-3 text-center text-sm text-ui-ink-gray-400"
							>
								Tidak ada aksi tersedia untuk Anda.
							</p>
							<div v-else class="max-h-[55vh] space-y-2 overflow-y-auto px-0.5">
								<!-- Transisi workflow (Frappe core) -->
								<button
									v-for="t in transitions.items"
									:key="t.action"
									type="button"
									:disabled="!!transitions.applying || amendState.applying"
									class="flex w-full items-center justify-between gap-2 rounded-2xl border border-ui-line-gray-200 px-4 py-3.5 text-left transition hover:border-primary hover:bg-primary/5 disabled:opacity-50"
									@click="applyAction(t.action)"
								>
									<span class="text-sm font-semibold text-ui-ink-gray-800">{{
										t.action
									}}</span>
									<span class="shrink-0 text-xs text-ui-ink-gray-400"
										>→ {{ t.next_state }}</span
									>
								</button>
								<!-- Amend (dokumen Cancelled) → buat draft amandemen -->
								<button
									v-if="amendState.can"
									type="button"
									:disabled="!!transitions.applying || amendState.applying"
									class="flex w-full items-center justify-between gap-2 rounded-2xl border border-ui-line-gray-200 px-4 py-3.5 text-left transition hover:border-primary hover:bg-primary/5 disabled:opacity-50"
									@click="doAmend"
								>
									<span
										class="flex items-center gap-2 text-sm font-semibold text-ui-ink-gray-800"
									>
										<svg
											xmlns="http://www.w3.org/2000/svg"
											viewBox="0 0 24 24"
											class="h-4 w-4 text-primary"
											fill="none"
											stroke="currentColor"
											stroke-width="2"
											stroke-linecap="round"
											stroke-linejoin="round"
										>
											<path d="M12 20h9" />
											<path
												d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z"
											/>
										</svg>
										Amend
									</span>
									<span class="shrink-0 text-xs text-ui-ink-gray-400"
										>→ Draft baru</span
									>
								</button>
							</div>
							<p
								v-if="transitions.applying || amendState.applying"
								class="mt-3 text-center text-xs text-ui-ink-gray-400"
							>
								{{
									amendState.applying
										? 'Membuat amendment…'
										: `Menerapkan “${transitions.applying}”…`
								}}
							</p>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>
	</div>
</template>

<script setup>
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import { statusPillClass } from '../data/stplStatus'
import { refreshCsrfToken } from '../data/session'
import { currentUser, loadMyRoles } from '../data/user'
import { openAttachment } from '../composables/pdfViewer'
import { notifyError, notifySuccess } from '../composables/toast'
import SelectMenu from '../components/SelectMenu.vue'

const DOCTYPE = 'STPL Unit Hilang'
const route = useRoute()
const router = useRouter()
const name = computed(() => route.params.name)

// Mode Amend: route 'StplUnitHilangAmend' (path /stpl-unit-hilang/amend/:from).
// Menampilkan salinan amandemen (dari dokumen Cancelled `from`) sebagai DRAFT
// BELUM TERSIMPAN dalam edit mode — persis desk: Save baru membuat dokumen Draft.
const isAmend = computed(() => route.name === 'StplUnitHilangAmend')
const amendFrom = computed(() => (isAmend.value ? String(route.params.from || '') : ''))
const amendReady = ref(false)

const displayTitle = computed(() => {
	if (isAmend.value) return `Amendment dari ${amendFrom.value}`
	return doc.data?.name || name.value
})
const displayStatus = computed(() => (isAmend.value ? form.status : doc.data?.status))
const pageLoading = computed(() => (isAmend.value ? !amendReady.value : doc.loading))

// Textarea auto-tinggi (dipakai via v-autogrow).
const AUTOGROW_MAX = 180
function fitTextarea(el) {
	if (!el) return
	el.style.height = 'auto'
	const h = Math.min(Math.max(el.scrollHeight, 44), AUTOGROW_MAX)
	el.style.height = `${h}px`
	el.style.overflowY = el.scrollHeight > AUTOGROW_MAX ? 'auto' : 'hidden'
}
const vAutogrow = {
	mounted(el) {
		el.addEventListener('input', () => fitTextarea(el))
		nextTick(() => fitTextarea(el))
	},
	updated(el) {
		nextTick(() => fitTextarea(el))
	},
}

// ---- Fetch dokumen ---------------------------------------------------------
const doc = createResource({
	url: 'frappe.client.get',
	makeParams() {
		return { doctype: DOCTYPE, name: name.value }
	},
	auto: false,
	onSuccess() {
		syncFormFromDoc()
	},
})

// ---- Meta doctype ----------------------------------------------------------
const metaFields = ref([])
const SKIP_TYPES = [
	'Section Break',
	'Column Break',
	'Tab Break',
	'HTML',
	'Button',
	'Heading',
	'Fold',
	'Barcode',
]
// Field yang tidak berguna ditampilkan di detail (housekeeping + audit internal).
// Section "Audit" disembunyikan agar selaras dengan tampilan Frappe core (field
// audit read-only & kosong sampai proses verifikasi/approval). Section Break
// "audit_section" ikut hilang otomatis karena tak lagi punya field anak.
const SKIP_FIELDS = [
	'amended_from',
	'audit_section',
	'diverifikasi_oleh',
	'diverifikasi_pada',
	'column_break_audit',
	'disetujui_oleh',
	'disetujui_pada',
]

function isTextarea(ft) {
	return ['Small Text', 'Text', 'Long Text', 'Code', 'Text Editor'].includes(ft)
}
function isImageField(ft) {
	return ['Image', 'Attach Image'].includes(ft)
}
function isNumberField(ft) {
	return ['Int', 'Float', 'Currency', 'Percent'].includes(ft)
}
function selectOptions(field) {
	return String(field.options || '')
		.split('\n')
		.map((s) => s.trim())
		.filter(Boolean)
}

// ---- Editabilitas: mengikuti workflow allow_edit (mirror desk) --------------
const editMode = ref(false)
const wfStateField = ref(null)
const wfEditStates = ref({})
const wfLoaded = ref(false)
async function loadWorkflowEditMap() {
	try {
		const params = new URLSearchParams({ doctype: DOCTYPE })
		const res = await fetch(
			`/api/method/juragan.api.portal.meta.get_workflow_edit_map?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (res.ok) {
			const msg = (await res.json()).message || {}
			wfStateField.value = msg.state_field || null
			wfEditStates.value = msg.states || {}
		}
	} catch (e) {
		/* fallback: tanpa data workflow → anggap tak boleh edit (aman) */
	} finally {
		wfLoaded.value = true
	}
}

// Permlevel yang boleh dibaca/ditulis user (sumber kebenaran = Meta Frappe).
const readablePermlevels = ref(new Set([0]))
const writablePermlevels = ref(new Set([0]))
async function loadPermlevelAccess() {
	try {
		const params = new URLSearchParams({ doctype: DOCTYPE })
		const res = await fetch(
			`/api/method/juragan.api.portal.meta.get_permlevel_access?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (res.ok) {
			const msg = (await res.json()).message || {}
			readablePermlevels.value = new Set(msg.read || [0])
			writablePermlevels.value = new Set(msg.write || [0])
		}
	} catch (e) {
		/* fallback: hanya permlevel 0 */
	}
}

// Boleh edit dokumen? None workflow → true; selain itu user punya salah satu
// role allow_edit pada status ini.
//
// STPL Unit Hilang submittable: begitu ter-submit (docstatus 1 = Approved) atau
// dibatalkan (docstatus 2 = Cancelled), Frappe mengunci dokumen jadi read-only
// (hanya bisa diubah lewat Amend). Ikuti persis: edit HANYA saat docstatus 0
// (Draft / Menunggu Approval / Rejected) — meski workflow state Approved punya
// allow_edit Administrator, dokumen submitted tetap tidak boleh diedit.
const canEditDoc = computed(() => {
	// Mode Amend = draft baru belum tersimpan → selalu editable.
	if (isAmend.value) return true
	if (!wfLoaded.value || !currentUser.rolesLoaded) return false
	if (doc.data?.docstatus !== 0) return false
	if (!wfStateField.value) return true
	const status = doc.data?.status
	if (!status) return true
	const allow = wfEditStates.value[status] || []
	const mine = currentUser.roles || []
	return allow.some((r) => mine.includes(r))
})

function enterEditMode() {
	if (canEditDoc.value) editMode.value = true
}
function cancelEdit() {
	// Batal saat Amend → tinggalkan draft, kembali ke dokumen sumber.
	if (isAmend.value) {
		router.replace({ name: 'StplUnitHilangDetail', params: { name: amendFrom.value } })
		return
	}
	syncFormFromDoc()
	editMode.value = false
	openDropdown.value = ''
}
// Begitu tak-boleh-edit (mis. pindah state) → kunci lagi.
watch(canEditDoc, (can) => {
	if (!can) editMode.value = false
})

// ---- Form editable ---------------------------------------------------------
const form = reactive({})
const saving = ref(false)

// Isi form dari objek sumber (dokumen tersimpan ATAU draft amandemen mentah).
function loadForm(src) {
	Object.assign(form, src || {})
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && form[f.fieldname] != null && form[f.fieldname] !== '') {
			form[f.fieldname] = String(form[f.fieldname])
		}
	}
	resolveAllLinks()
}
function syncFormFromDoc() {
	// Jangan timpa draft amandemen dengan data dokumen (amend tidak fetch doc).
	if (isAmend.value) return
	loadForm(doc.data)
}

const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

// ---- Kondisi depends_on / read_only / reqd ---------------------------------
function evalCondition(expr) {
	if (!expr) return true
	try {
		const code = String(expr).replace(/^eval:/, '')
		const in_list = (list, item) => Array.isArray(list) && list.includes(item)
		const cint = (v) => parseInt(v, 10) || 0
		const cstr = (v) => (v == null ? '' : String(v))
		const flt = (v) => parseFloat(v) || 0
		// eslint-disable-next-line no-new-func
		return !!new Function('doc', 'in_list', 'cint', 'cstr', 'flt', `return (${code})`)(
			form,
			in_list,
			cint,
			cstr,
			flt
		)
	} catch (e) {
		return true
	}
}
function isFieldReqd(field) {
	if (field.reqd) return true
	return field.mandatory_depends_on ? evalCondition(field.mandatory_depends_on) : false
}
function isFieldReadOnly(field) {
	if (!editMode.value) return true
	if (field.read_only) return true
	if (!writablePermlevels.value.has(field.permlevel || 0)) return true
	return field.read_only_depends_on ? evalCondition(field.read_only_depends_on) : false
}
function fieldClass(field) {
	return [
		inputClass,
		isFieldReadOnly(field)
			? '!bg-ui-surface-gray-100 !text-ui-ink-gray-500 !border-ui-line-gray-200 cursor-not-allowed'
			: '',
	]
}

// ---- Format nilai ----------------------------------------------------------
function formatCurrency(v) {
	const n = Number(v)
	if (v === '' || v == null || Number.isNaN(n)) return String(v ?? '')
	return new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	}).format(n)
}
function currencyDisplay(v) {
	if (v === '' || v == null || Number.isNaN(Number(v))) return ''
	return `Rp ${formatCurrency(v)}`
}
function formatDateDisplay(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}
function parseCurrency(str) {
	if (str == null) return ''
	const cleaned = String(str)
		.replace(/\./g, '')
		.replace(',', '.')
		.replace(/[^\d.]/g, '')
	if (cleaned === '') return ''
	const n = Number(cleaned)
	return Number.isNaN(n) ? '' : n
}
function onCurrencyBlur(field, e) {
	const n = parseCurrency(e.target.value)
	form[field.fieldname] = n
	e.target.value = currencyDisplay(n)
}
function fileName(url) {
	if (!url) return ''
	const clean = String(url).split('?')[0]
	return decodeURIComponent(clean.substring(clean.lastIndexOf('/') + 1)) || clean
}

// ---- Link searchable + resolusi judul --------------------------------------
const linkTitleField = reactive({})
const linkTitles = reactive({})
const linkOptions = reactive({})

async function loadLinkMeta() {
	const dts = new Set()
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && f.options) dts.add(f.options)
	}
	await Promise.all(
		[...dts].map(async (dt) => {
			try {
				const res = await fetch(
					`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(
						dt
					)}`,
					{
						method: 'GET',
						credentials: 'include',
						headers: { Accept: 'application/json' },
					}
				)
				const json = await res.json()
				const docs = json.docs || json.message?.docs || []
				const meta = docs.find((x) => x.name === dt) || docs[0]
				linkTitleField[dt] = (meta && meta.title_field) || null
			} catch (e) {
				linkTitleField[dt] = null
			}
		})
	)
	resolveAllLinks()
	for (const dt of dts) loadLinkOptions(dt)
}
async function loadLinkOptions(dt) {
	if (linkOptions[dt]) return
	const titleField = linkTitleField[dt]
	try {
		const flds = titleField ? ['name', titleField] : ['name']
		const lparams = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(flds),
			limit_page_length: '101',
			order_by: 'name asc',
		})
		const lres = await fetch(`/api/method/frappe.client.get_list?${lparams.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const ljson = await lres.json()
		const recs = ljson.message || []
		if (recs.length && recs.length <= 100) {
			linkOptions[dt] = recs.map((r) => ({
				value: String(r.name),
				label: (titleField && r[titleField]) || String(r.name),
			}))
		}
	} catch (e) {
		/* abaikan */
	}
}
async function resolveLinkTitle(dt, value) {
	const key = `${dt}:${value}`
	if (value == null || value === '' || linkTitles[key] !== undefined) return
	const titleField = linkTitleField[dt]
	if (titleField === undefined) return
	if (titleField === null) {
		linkTitles[key] = String(value)
		return
	}
	try {
		const params = new URLSearchParams({
			doctype: dt,
			fieldname: titleField,
			filters: String(value),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		const msg = json.message
		const title = msg && typeof msg === 'object' ? msg[titleField] : msg
		linkTitles[key] = title != null && title !== '' ? title : String(value)
	} catch (e) {
		linkTitles[key] = String(value)
	}
}
function resolveAllLinks() {
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && f.options && form[f.fieldname]) {
			resolveLinkTitle(f.options, form[f.fieldname])
		}
	}
}
function linkDisplay(field) {
	const v = form[field.fieldname]
	if (!v) return ''
	const opts = linkOptions[field.options]
	if (opts) {
		const cur = opts.find((o) => String(o.value).toLowerCase() === String(v).toLowerCase())
		if (cur) return cur.label
	}
	const t = linkTitles[`${field.options}:${v}`]
	if (t !== undefined) return t
	if (linkTitleField[field.options] === null) return v
	return '…'
}

const openDropdown = ref('')
const linkSearch = ref('')
const linkResults = ref([])
const linkSearchLoading = ref(false)
function optionMatch(opt, field) {
	const v = form[field.fieldname]
	if (v == null || v === '') return false
	return String(opt.value).toLowerCase() === String(v).toLowerCase()
}
function linkFilters(field) {
	let raw = field.link_filters
	if (!raw) return []
	try {
		if (typeof raw === 'string') raw = JSON.parse(raw)
	} catch (e) {
		return []
	}
	const out = []
	const push = (f, op, v) => {
		if (typeof v === 'string' && /^eval:|^doc\./.test(v)) return
		out.push([f, op, v])
	}
	if (Array.isArray(raw)) {
		for (const c of raw) {
			if (!Array.isArray(c)) continue
			if (c.length === 4) push(c[1], c[2], c[3])
			else if (c.length === 3) push(c[0], c[1], c[2])
		}
	} else if (raw && typeof raw === 'object') {
		for (const [k, v] of Object.entries(raw)) push(k, '=', v)
	}
	return out
}
function toggleLinkDropdown(field) {
	if (openDropdown.value === field.fieldname) {
		openDropdown.value = ''
		return
	}
	openDropdown.value = field.fieldname
	linkSearch.value = ''
	const opts = linkFilters(field).length ? null : linkOptions[field.options]
	if (opts) linkResults.value = opts
	else fetchLinkResults(field, '')
}
async function fetchLinkResults(field, query) {
	const dt = field.options
	const titleField = linkTitleField[dt]
	linkSearchLoading.value = true
	linkResults.value = []
	try {
		const flds = titleField ? ['name', titleField] : ['name']
		const params = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(flds),
			limit_page_length: '20',
			order_by: 'name asc',
		})
		const lf = linkFilters(field)
		if (lf.length) params.set('filters', JSON.stringify(lf))
		if (query) {
			const ors = [['name', 'like', `%${query}%`]]
			if (titleField) ors.push([titleField, 'like', `%${query}%`])
			params.set('or_filters', JSON.stringify(ors))
		}
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		const recs = json.message || []
		linkResults.value = recs.map((r) => ({
			value: String(r.name),
			label: (titleField && r[titleField]) || String(r.name),
		}))
	} catch (e) {
		linkResults.value = []
	} finally {
		linkSearchLoading.value = false
	}
}
let linkSearchTimer = null
function onLinkSearch(field) {
	const q = linkSearch.value.trim()
	const opts = linkFilters(field).length ? null : linkOptions[field.options]
	if (opts) {
		const ql = q.toLowerCase()
		linkResults.value = ql
			? opts.filter(
					(o) =>
						o.label.toLowerCase().includes(ql) ||
						String(o.value).toLowerCase().includes(ql)
			  )
			: opts
		return
	}
	clearTimeout(linkSearchTimer)
	linkSearchTimer = setTimeout(() => fetchLinkResults(field, q), 300)
}
function selectLink(field, value, label) {
	form[field.fieldname] = value
	if (label != null) linkTitles[`${field.options}:${value}`] = label
	openDropdown.value = ''
}

// ---- Upload Attach ---------------------------------------------------------
const fileInput = ref(null)
const pendingUploadField = ref(null)
const uploadingField = ref('')
function triggerUpload(field) {
	if (isFieldReadOnly(field)) return
	pendingUploadField.value = field
	if (fileInput.value) {
		fileInput.value.value = ''
		fileInput.value.click()
	}
}
async function onFileChange(e) {
	const file = e.target.files?.[0]
	const f = pendingUploadField.value
	if (!file || !f) return
	const MAX_MB = 3
	if (file.size > MAX_MB * 1024 * 1024) {
		notifyError(`Ukuran file maksimal ${MAX_MB} MB.`, 'Gagal mengunggah file')
		pendingUploadField.value = null
		return
	}
	uploadingField.value = f.fieldname
	try {
		const fd = new FormData()
		fd.append('file', file, file.name)
		fd.append('upload_doctype', DOCTYPE)
		fd.append('is_private', '1')
		const res = await fetch('/api/method/upload_file', {
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: fd,
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
		form[f.fieldname] = json.message?.file_url || ''
	} catch (err) {
		notifyError(err, 'Gagal mengunggah file')
	} finally {
		uploadingField.value = ''
		pendingUploadField.value = null
	}
}

// ---- Susun section dari meta -----------------------------------------------
const sectionsStructure = computed(() => {
	const sections = []
	let curSection = null
	let curCol = null
	const ensureSection = () => {
		if (!curSection) {
			curCol = []
			curSection = { label: '', columns: [curCol] }
			sections.push(curSection)
		}
	}
	for (const f of metaFields.value) {
		const ft = f.fieldtype
		if (ft === 'Section Break') {
			curCol = []
			curSection = { label: f.label || '', columns: [curCol] }
			sections.push(curSection)
			continue
		}
		if (ft === 'Column Break') {
			if (!curSection) ensureSection()
			else {
				curCol = []
				curSection.columns.push(curCol)
			}
			continue
		}
		if (SKIP_TYPES.includes(ft) || SKIP_FIELDS.includes(f.fieldname)) continue
		ensureSection()
		curCol.push(f)
	}
	return sections
})

// Field terlihat: tidak hidden, permlevel boleh dibaca, depends_on terpenuhi.
function fieldVisible(f) {
	if (f.hidden) return false
	if (!readablePermlevels.value.has(f.permlevel || 0)) return false
	if (f.depends_on && !evalCondition(f.depends_on)) return false
	return true
}
function hasValue(f) {
	const v = doc.data?.[f.fieldname]
	if (f.fieldtype === 'Check') return !!v
	return !(v == null || (typeof v === 'string' && v.trim() === ''))
}

// Section yang dirender. Mode edit → semua field terlihat & bisa ditulis atau
// wajib; mode baca → hanya field terlihat yang ada isinya.
const renderedSections = computed(() => {
	const out = []
	for (const sec of sectionsStructure.value) {
		const columns = sec.columns
			.map((col) =>
				col.filter((f) => {
					if (!fieldVisible(f)) return false
					if (editMode.value) return true
					return hasValue(f)
				})
			)
			.filter((col) => col.length)
		if (columns.length) out.push({ ...sec, columns })
	}
	return out
})

// ---- Simpan ----------------------------------------------------------------
function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}
async function saveDoc(docObj) {
	const res = await fetch('/api/method/frappe.client.save', {
		method: 'POST',
		credentials: 'include',
		headers: {
			'Content-Type': 'application/json',
			Accept: 'application/json',
			'X-Frappe-CSRF-Token': window.csrf_token || '',
		},
		body: JSON.stringify({ doc: docObj }),
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
	return json.message
}
async function saveDocument() {
	saving.value = true
	try {
		const payload = JSON.parse(JSON.stringify(form))
		payload.doctype = DOCTYPE
		if (isAmend.value) {
			// Amend: draft baru → INSERT (tanpa name). frappe.client.save meng-insert
			// dokumen baru (docstatus 0) bila belum punya name; penamaan "-N" &
			// salin lampiran ditangani server. Setelah tersimpan → buka detail asli.
			delete payload.name
			payload.docstatus = 0
			const saved = await saveDoc(payload)
			notifySuccess('Draft amandemen berhasil dibuat.')
			router.replace({ name: 'StplUnitHilangDetail', params: { name: saved?.name } })
			return
		}
		payload.name = name.value
		await saveDoc(payload)
		await doc.fetch()
		editMode.value = false
		loadTransitions()
		loadCanAmend()
		notifySuccess('Perubahan berhasil disimpan.')
	} catch (e) {
		notifyError(e, 'Gagal menyimpan')
	} finally {
		saving.value = false
	}
}

// ---- Actions workflow (transisi dari Frappe core) --------------------------
const actionsOpen = ref(false)
const transitions = reactive({ loading: false, items: [], applying: '' })

async function loadTransitions() {
	if (!doc.data) return
	transitions.loading = true
	try {
		const res = await fetch('/api/method/frappe.model.workflow.get_transitions', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: doc.data }),
		})
		const json = await res.json()
		transitions.items = json.message || []
	} catch (e) {
		transitions.items = []
	} finally {
		transitions.loading = false
	}
}
async function applyAction(action) {
	transitions.applying = action
	try {
		const res = await fetch('/api/method/frappe.model.workflow.apply_workflow', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: doc.data, action }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		actionsOpen.value = false
		await doc.fetch()
		loadTransitions()
		loadCanAmend()
		notifySuccess(`Aksi "${action}" berhasil diterapkan.`)
	} catch (e) {
		actionsOpen.value = false
		notifyError(e, `Gagal menerapkan aksi "${action}"`)
	} finally {
		transitions.applying = ''
	}
}

// ---- Amend (Frappe core: dokumen Cancelled bisa dibuat draft amandemennya) --
// Aksi Amend BUKAN transisi workflow — di desk ia tombol terpisah pada dokumen
// docstatus 2. Gate & eksekusinya di server (juragan.api.portal.stpl), yang meniru
// frappe.copy_doc + insert (penamaan "-N", salin lampiran, reset audit).
const amendState = reactive({ can: false, applying: false })

async function loadCanAmend() {
	amendState.can = false
	if (doc.data?.docstatus !== 2) return
	try {
		const params = new URLSearchParams({ name: name.value })
		const res = await fetch(
			`/api/method/juragan.api.portal.stpl.can_amend?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (res.ok) amendState.can = !!(await res.json()).message
	} catch (e) {
		amendState.can = false
	}
}

// Klik Amend → buka mode Amend (draft belum tersimpan, edit mode). TIDAK meng-insert
// di sini; dokumen baru dibuat saat Save. Persis alur desk (amend_doc → form baru).
function doAmend() {
	actionsOpen.value = false
	router.push({ name: 'StplUnitHilangAmend', params: { from: name.value } })
}

// Muat draft amandemen (prepare_amend, TANPA insert) lalu masuk edit mode.
async function loadAmendDraft() {
	try {
		const params = new URLSearchParams({ name: amendFrom.value })
		const res = await fetch(
			`/api/method/juragan.api.portal.stpl.prepare_amend?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		loadForm(json.message || {})
		editMode.value = true
		amendReady.value = true
	} catch (e) {
		notifyError(e, 'Gagal menyiapkan amend')
		amendReady.value = true
	}
}

// Bottom bar tampil bila: mode Amend, mode edit, ada aksi workflow, atau bisa di-amend.
const showBottomBar = computed(
	() =>
		isAmend.value ||
		(!!doc.data && (editMode.value || transitions.items.length > 0 || amendState.can))
)

// ---- Muat meta -------------------------------------------------------------
async function loadMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(DOCTYPE)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const dt = docs.find((x) => x.name === DOCTYPE) || docs[0]
		metaFields.value = (dt && dt.fields) || []
		if (!isAmend.value) syncFormFromDoc()
		loadLinkMeta().catch(() => {})
	} catch (e) {
		/* meta gagal → section tidak terbentuk */
	}
}

// Inisialisasi konten untuk route saat ini. Dipanggil di mount DAN saat route
// berubah — komponen ini dipakai ulang antara detail ⇄ amend (param berubah tapi
// instance sama), jadi onMounted saja tidak cukup.
async function initPage() {
	editMode.value = false
	amendReady.value = false
	transitions.items = []
	amendState.can = false
	openDropdown.value = ''
	if (isAmend.value) {
		// Mode Amend: siapkan draft dari sumber (Cancelled), jangan fetch dokumen.
		await loadAmendDraft()
	} else {
		await doc.fetch()
		loadTransitions()
		loadCanAmend()
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	loadMyRoles()
	await Promise.all([loadMeta(), loadWorkflowEditMap(), loadPermlevelAccess()])
	await initPage()
})

// Navigasi detail ⇄ amend / antar-detail (instance dipakai ulang) → muat ulang.
watch(
	() => route.fullPath,
	() => initPage()
)
</script>
